package com.loja.checkout.dominio;

import java.math.BigDecimal;

/**
 * Cupons da loja. Cada promoção guarda a sua própria condição e a sua própria
 * conta de desconto, então uma promoção nova é só uma constante nova.
 */
public enum Cupom {

    BEMVINDO10 {
        @Override
        public BigDecimal desconto(ContextoCupom contexto) {
            return Dinheiro.percentual(contexto.subtotalProdutos(), new BigDecimal("0.10"));
        }
    },

    MENOS50 {
        private static final BigDecimal MINIMO = new BigDecimal("300.00");

        @Override
        public boolean aplicavel(ContextoCupom contexto) {
            return contexto.subtotalProdutos().compareTo(MINIMO) >= 0;
        }

        @Override
        public BigDecimal desconto(ContextoCupom contexto) {
            return Dinheiro.centavos(new BigDecimal("50.00"));
        }
    },

    FRETEGRATIS {
        @Override
        public BigDecimal desconto(ContextoCupom contexto) {
            return Dinheiro.centavos(contexto.frete());
        }
    },

    LEVE3PAGUE2 {
        @Override
        public BigDecimal desconto(ContextoCupom contexto) {
            BigDecimal desconto = BigDecimal.ZERO;
            for (Item item : contexto.itens()) {
                int gratuitas = item.quantidade() / 3;
                desconto = desconto.add(item.precoUnitario().multiply(BigDecimal.valueOf(gratuitas)));
            }
            return Dinheiro.centavos(desconto);
        }
    };

    /** Se o pedido cumpre a condição da promoção. */
    public boolean aplicavel(ContextoCupom contexto) {
        return true;
    }

    public abstract BigDecimal desconto(ContextoCupom contexto);
}
EOF
