1	package com.loja.checkout.web;
2	
3	import com.loja.checkout.dominio.CheckoutException;
4	import com.loja.checkout.dominio.ContextoCupom;
5	import com.loja.checkout.dominio.Cupom;
6	import com.loja.checkout.dominio.Dinheiro;
7	import com.loja.checkout.dominio.ErroCheckout;
8	import com.loja.checkout.dominio.FormaPagamento;
9	import com.loja.checkout.dominio.Item;
10	import com.loja.checkout.dominio.ModalidadeEntrega;
11	import com.loja.checkout.dominio.NivelClube;
12	import com.loja.checkout.dominio.Regiao;
13	import com.loja.checkout.dominio.ResumoCompra;
14	import com.loja.checkout.dominio.ValorCobrado;
15	import com.loja.checkout.web.ResumoRequest.ItemRequest;
16	import java.math.BigDecimal;
17	import java.util.List;
18	import java.util.Optional;
19	import org.springframework.stereotype.Service;
20	
21	/**
22	 * A parte do cálculo que é igual em todos os casos: confere o pedido na ordem
23	 * definida, pede a cada opção escolhida o seu pedaço e monta o resumo.
24	 */
25	@Service
26	public class CheckoutService {
27	
28	    private static final int PARCELA_UNICA = 1;
29	
30	    public ResumoCompra calcular(ResumoRequest pedido) {
31	        ResumoRequest dados = Optional.ofNullable(pedido)
32	                .orElseThrow(() -> new CheckoutException(ErroCheckout.PEDIDO_INVALIDO));
33	
34	        List<Item> itens = itensValidos(dados.itens());
35	        NivelClube nivel = opcao(NivelClube.class, dados.nivelClube(), ErroCheckout.NIVEL_CLUBE_INVALIDO);
36	        Regiao regiao = opcao(Regiao.class, dados.regiao(), ErroCheckout.REGIAO_INVALIDA);
37	        ModalidadeEntrega entrega =
38	                opcao(ModalidadeEntrega.class, dados.modalidadeEntrega(), ErroCheckout.MODALIDADE_INVALIDA);
39	
40	        BigDecimal subtotalProdutos = somar(itens.stream().map(Item::total).toList());
41	        BigDecimal pesoKg = itens.stream().map(Item::peso).reduce(BigDecimal.ZERO, BigDecimal::add);
42	
43	        exigir(entrega.atende(pesoKg), ErroCheckout.MODALIDADE_INDISPONIVEL);
44	        BigDecimal frete = nivel.freteDevido(entrega.frete(pesoKg));
45	
46	        Optional<Cupom> cupom = cupomInformado(dados.cupom());
47	        ContextoCupom contexto = new ContextoCupom(itens, subtotalProdutos, frete);
48	        cupom.ifPresent(c -> exigir(c.aplicavel(contexto), ErroCheckout.CUPOM_NAO_APLICAVEL));
49	        BigDecimal descontoCupom = cupom.map(c -> c.desconto(contexto)).orElse(Dinheiro.ZERO);
50	
51	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
52	        BigDecimal totalPedido = Dinheiro.centavos(
53	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
54	
55	        FormaPagamento pagamento =
56	                opcao(FormaPagamento.class, dados.formaPagamento(), ErroCheckout.FORMA_PAGAMENTO_INVALIDA);
57	        int parcelas = Optional.ofNullable(dados.parcelas()).orElse(PARCELA_UNICA);
58	        exigir(pagamento.permiteParcelas(parcelas), ErroCheckout.PARCELAMENTO_INVALIDO);
59	        exigir(pagamento.atende(totalPedido), ErroCheckout.FORMA_PAGAMENTO_INDISPONIVEL);
60	        ValorCobrado cobrado = pagamento.cobrar(totalPedido, parcelas);
61	
62	        return new ResumoCompra(
63	                subtotalProdutos,
64	                descontoCupom,
65	                Dinheiro.centavos(frete),
66	                entrega.prazoDias(),
67	                seguro,
68	                Dinheiro.centavos(cobrado.totalFinal().subtract(totalPedido)),
69	                cobrado.totalFinal(),
70	                parcelas,
71	                cobrado.valorParcela(),
72	                nivel.credito(subtotalProdutos),
73	                nivel.brinde(subtotalProdutos));
74	    }
75	
76	    private static List<Item> itensValidos(List<ItemRequest> itens) {
77	        exigir(itens != null && !itens.isEmpty(), ErroCheckout.PEDIDO_INVALIDO);
78	        return itens.stream().map(CheckoutService::itemValido).toList();
79	    }
80	
81	    private static Item itemValido(ItemRequest item) {
82	        exigir(item != null, ErroCheckout.PEDIDO_INVALIDO);
83	        exigir(positivo(item.precoUnitario()), ErroCheckout.PEDIDO_INVALIDO);
84	        exigir(item.quantidade() != null && item.quantidade() > 0, ErroCheckout.PEDIDO_INVALIDO);
85	        exigir(positivo(item.pesoKg()), ErroCheckout.PEDIDO_INVALIDO);
86	        return new Item(item.nome(), item.precoUnitario(), item.quantidade(), item.pesoKg());
87	    }
88	
89	    private static boolean positivo(BigDecimal valor) {
90	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
91	    }
92	
93	    private static Optional<Cupom> cupomInformado(String codigo) {
94	        return Optional.ofNullable(codigo)
95	                .map(c -> opcao(Cupom.class, c, ErroCheckout.CUPOM_INVALIDO));
96	    }
97	
98	    /** Traduz o texto que o site manda na opção correspondente, ou recusa o pedido. */
99	    private static <O extends Enum<O>> O opcao(Class<O> tipo, String valor, ErroCheckout erro) {
100	        exigir(valor != null, erro);
101	        try {
102	            return Enum.valueOf(tipo, valor);
103	        } catch (IllegalArgumentException desconhecida) {
104	            throw new CheckoutException(erro);
105	        }
106	    }
107	
108	    private static void exigir(boolean condicao, ErroCheckout erro) {
109	        if (!condicao) {
110	            throw new CheckoutException(erro);
111	        }
112	    }
113	
114	    private static BigDecimal somar(List<BigDecimal> valores) {
115	        return Dinheiro.centavos(valores.stream().reduce(BigDecimal.ZERO, BigDecimal::add));
116	    }
117	}
118

