6	/**
7	 * Regra de dinheiro comum a todas as etapas: valores em centavos, arredondados
8	 * com "meio para o par".
9	 */
10	public final class Dinheiro {
11	
12	    public static final BigDecimal ZERO = centavos(BigDecimal.ZERO);
13	
14	    private Dinheiro() {
15	    }
16	
17	    public static BigDecimal centavos(BigDecimal valor) {
18	        return valor.setScale(2, RoundingMode.HALF_EVEN);
19	    }
20	
21	    /** Percentual sobre uma base, já em centavos. O percentual vem como fração (0.025 = 2,5%). */
22	    public static BigDecimal percentual(BigDecimal base, BigDecimal fracao) {
23	        return centavos(base.multiply(fracao));
24	    }
25	}
