1	package com.loja.checkout.dominio;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	
6	/**
7	 * Formas de pagamento. Cada uma sabe em quantas vezes aceita ser parcelada, se
8	 * atende o pedido e como transforma o total do pedido em valor final e parcela.
9	 */
10	public enum FormaPagamento {
11	
12	    PIX {
13	        private static final BigDecimal DESCONTO = new BigDecimal("0.05");
14	
15	        @Override
16	        public ValorCobrado cobrar(BigDecimal totalPedido, int parcelas) {
17	            return ValorCobrado.aVista(totalPedido.subtract(Dinheiro.percentual(totalPedido, DESCONTO)));
18	        }
19	    },
20	
21	    BOLETO {
22	        private static final BigDecimal TARIFA = new BigDecimal("3.49");
23	        private static final BigDecimal TOTAL_MAXIMO = new BigDecimal("1000.00");
24	
25	        @Override
26	        public ValorCobrado cobrar(BigDecimal totalPedido, int parcelas) {
27	            return ValorCobrado.aVista(totalPedido.add(TARIFA));
28	        }
29	
30	        @Override
31	        public boolean atende(BigDecimal totalPedido) {
32	            return totalPedido.compareTo(TOTAL_MAXIMO) <= 0;
33	        }
34	    },
35	
36	    CARTAO {
37	        private static final MathContext PRECISAO = MathContext.DECIMAL128;
38	        private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
39	        private static final int MAXIMO_SEM_JUROS = 3;
40	        private static final int MAXIMO_PARCELAS = 12;
41	
42	        @Override
43	        public boolean permiteParcelas(int parcelas) {
44	            return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
45	        }
46	
47	        @Override
48	        public ValorCobrado cobrar(BigDecimal totalPedido, int parcelas) {
49	            if (parcelas <= MAXIMO_SEM_JUROS) {
50	                return new ValorCobrado(
51	                        Dinheiro.centavos(totalPedido),
52	                        Dinheiro.centavos(totalPedido.divide(BigDecimal.valueOf(parcelas), PRECISAO)));
53	            }
54	            BigDecimal parcela = Dinheiro.centavos(tabelaPrice(totalPedido, parcelas));
55	            return new ValorCobrado(
56	                    Dinheiro.centavos(parcela.multiply(BigDecimal.valueOf(parcelas))),
57	                    parcela);
58	        }
59	
60	        /** parcela = total x taxa / (1 - (1 + taxa)^-parcelas) */
61	        private static BigDecimal tabelaPrice(BigDecimal totalPedido, int parcelas) {
62	            BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, PRECISAO);
63	            BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, PRECISAO));
64	            return totalPedido.multiply(TAXA_MENSAL).divide(divisor, PRECISAO);
65	        }
66	    };
67	
68	    /** Quantidades de parcelas que esta forma aceita. À vista, só uma. */
69	    public boolean permiteParcelas(int parcelas) {
70	        return parcelas == 1;
71	    }
72	
73	    /** Se a forma atende um pedido deste total. */
74	    public boolean atende(BigDecimal totalPedido) {
75	        return true;
76	    }
77	
78	    public abstract ValorCobrado cobrar(BigDecimal totalPedido, int parcelas);
79	}
